$authors = git log --format='%aN' | Sort-Object -Unique

foreach ($author in $authors) {
    $log = git log --author="$author" --pretty=tformat: --numstat
    $added = 0
    $removed = 0
    $commits = (git log --author="$author" --oneline | Measure-Object).Count

    foreach ($line in $log) {
        $parts = $line -split "`t"
        if ($parts.Length -ge 2) {
            if ($parts[0] -match '^\d+$') { $added += [int]$parts[0] }
            if ($parts[1] -match '^\d+$') { $removed += [int]$parts[1] }
        }
    }

    "$author | Commits: $commits | Added: $added | Removed: $removed | Total: $($added + $removed)"
}

(function () {
    var loaded = false;
    var events = ["scroll", "click", "touchstart", "keydown"];
    var opts = { passive: true, capture: true };
    function loadDeferredScript() {
        if (loaded) return;
        loaded = true;
        events.forEach(function (event) {
            window.removeEventListener(event, loadDeferredScript, opts);
        });
        var script = document.createElement("script");
        script.async = true;
        script.src = "https://example.com/your-script.js";
        document.head.appendChild(script);
    }
    events.forEach(function (event) {
        window.addEventListener(event, loadDeferredScript, opts);
    });
})();
